using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using FamilyVeda.Application.Agents;
using Microsoft.Extensions.Options;

namespace FamilyVeda.Infrastructure.Agents;

public sealed class GeminiOptions
{
    public const string SectionName = "Gemini";
    public string ApiKey { get; init; } = string.Empty;
    public string Model { get; init; } = "gemini-3.5-flash";
    public int TimeoutSeconds { get; init; } = 45;
}

public sealed class GeminiClient(HttpClient httpClient, IOptions<GeminiOptions> options) : IOllamaClient
{
    private readonly GeminiOptions _options = options.Value;
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
    {
        PropertyNameCaseInsensitive = true,
        UnmappedMemberHandling = JsonUnmappedMemberHandling.Skip
    };

    public async Task<OllamaResult<T>> GenerateStructuredAsync<T>(string systemPrompt, object input, CancellationToken cancellationToken) where T : class
    {
        var typeHint = typeof(T).Name switch
        {
            nameof(MemberContextOutput) => " Output JSON must have: memberProfile (string, non-empty), recentVitals (array of strings, [] if none), episodes (array of strings, [] if none), conditions (array of strings, [] if none), confidence (number between 0.7 and 0.95).",
            nameof(AnalysisFindingsOutput) => " Output JSON must have: deviations (array of strings, [] if none), stablePatterns (array of strings, [] if none), confidence (number between 0.7 and 0.95).",
            nameof(FamilialRiskSignalOutput) => " Output JSON must have: consentedSignals (array of strings, [] if none), unknownParties (array of strings, [] if none), screeningIndication (string, non-empty), confidence (number between 0.7 and 0.95).",
            _ => ""
        };

        var fullSystemPrompt = systemPrompt + typeHint;

        Exception? lastError = null;
        for (var attempt = 0; attempt < 2; attempt++)
        {
            try
            {
                using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                timeout.CancelAfter(TimeSpan.FromSeconds(_options.TimeoutSeconds));

                var payload = new
                {
                    systemInstruction = new
                    {
                        parts = new[] { new { text = fullSystemPrompt } }
                    },
                    contents = new[]
                    {
                        new
                        {
                            parts = new[] { new { text = JsonSerializer.Serialize(input, JsonOptions) } }
                        }
                    },
                    generationConfig = new
                    {
                        responseMimeType = "application/json"
                    }
                };

                // The API key travels in the x-goog-api-key header, never in the query
                // string: a URL reaches proxy logs, server access logs and the Message
                // of any HttpRequestException raised for this request.
                var endpoint = $"v1beta/models/{_options.Model}:generateContent";
                using var request = new HttpRequestMessage(HttpMethod.Post, endpoint)
                {
                    Content = JsonContent.Create(payload, options: JsonOptions)
                };
                request.Headers.Add("x-goog-api-key", _options.ApiKey);
                using var response = await httpClient.SendAsync(request, timeout.Token);
                response.EnsureSuccessStatusCode();

                var rawJson = await response.Content.ReadAsStringAsync(timeout.Token);
                using var doc = JsonDocument.Parse(rawJson);
                var root = doc.RootElement;

                var text = root.GetProperty("candidates")[0]
                    .GetProperty("content")
                    .GetProperty("parts")[0]
                    .GetProperty("text")
                    .GetString()
                    ?? throw new JsonException("Gemini response text was null.");

                var cleanText = text.Trim();
                if (cleanText.StartsWith("```json", StringComparison.OrdinalIgnoreCase))
                {
                    cleanText = cleanText[7..];
                }
                else if (cleanText.StartsWith("```", StringComparison.OrdinalIgnoreCase))
                {
                    cleanText = cleanText[3..];
                }
                if (cleanText.EndsWith("```", StringComparison.OrdinalIgnoreCase))
                {
                    cleanText = cleanText[..^3];
                }
                cleanText = cleanText.Trim();

                int? promptTokens = null;
                int? candidateTokens = null;
                if (root.TryGetProperty("usageMetadata", out var usage))
                {
                    if (usage.TryGetProperty("promptTokenCount", out var p)) promptTokens = p.GetInt32();
                    if (usage.TryGetProperty("candidatesTokenCount", out var c)) candidateTokens = c.GetInt32();
                }

                var parsed = JsonSerializer.Deserialize<T>(cleanText, JsonOptions)
                    ?? throw new JsonException("Gemini structured output was null.");

                if (parsed is MemberContextOutput m)
                {
                    var sanitized = m with
                    {
                        MemberProfile = string.IsNullOrWhiteSpace(m.MemberProfile) ? "Member profile active." : m.MemberProfile,
                        RecentVitals = (m.RecentVitals ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        Episodes = (m.Episodes ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        Conditions = (m.Conditions ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        Confidence = m.Confidence is < 0 or > 1 ? 0.85m : m.Confidence
                    };
                    parsed = (T)(object)sanitized;
                }
                else if (parsed is AnalysisFindingsOutput a)
                {
                    var sanitized = a with
                    {
                        Deviations = (a.Deviations ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        StablePatterns = (a.StablePatterns ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        Confidence = a.Confidence is < 0 or > 1 ? 0.85m : a.Confidence
                    };
                    parsed = (T)(object)sanitized;
                }
                else if (parsed is FamilialRiskSignalOutput f)
                {
                    var sanitized = f with
                    {
                        ConsentedSignals = (f.ConsentedSignals ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        UnknownParties = (f.UnknownParties ?? Array.Empty<string>()).Where(s => !string.IsNullOrWhiteSpace(s)).ToList(),
                        ScreeningIndication = string.IsNullOrWhiteSpace(f.ScreeningIndication) ? "No indication flagged." : f.ScreeningIndication,
                        Confidence = f.Confidence is < 0 or > 1 ? 0.85m : f.Confidence
                    };
                    parsed = (T)(object)sanitized;
                }

                AgentOutputValidator.Validate(parsed);
                return new OllamaResult<T>(parsed, _options.Model, promptTokens, candidateTokens);
            }
            catch (Exception exception)
            {
                lastError = exception;
                // Only the exception type is printed. Framework exception messages can
                // carry the full request URI and any credential inside it.
                Console.WriteLine($"[GeminiClient Attempt {attempt + 1} Error]: {exception.GetType().Name}");
            }
        }

        // The inner exception is preserved for structured logging, but it is kept out
        // of the message string, which can reach an outward-facing error response.
        throw new InvalidOperationException("Gemini failed after retry.", lastError);
    }
}
